/usr/bin/bash -lc "python - <<'PY'
from urllib.parse import urlsplit
for value in ['http://[v1.foo]/', 'http://[V1.foo]/', 'http://[::1]/', 'http://host:00080/']:
    try:
        u=urlsplit(value)
        print(value, u, u.hostname, u.port)
    except Exception as exc:
        print(value, type(exc).__name__, exc)
PY"

